import{_ as e,o as n,c as a,a3 as t}from"./chunks/framework.DVCfY5-a.js";const g=JSON.parse('{"title":"Capture And Inspect A Lab Recording","description":"","frontmatter":{"docLocale":"en","counterpart":"/tutorials/recording","contentType":"tutorial","prev":{"text":"Install a fixed scene and manage a Simulation Session","link":"/en/tutorials/simulation-session"},"next":{"text":"Spatial workbench","link":"/en/tutorials/spatial-workbench"}},"headers":[],"relativePath":"en/tutorials/recording.md","filePath":"en/tutorials/recording.md"}'),i={name:"en/tutorials/recording.md"};function p(r,s,l,o,d,c){return n(),a("div",null,[...s[0]||(s[0]=[t(`<h1 id="capture-and-inspect-a-lab-recording" tabindex="-1">Capture And Inspect A Lab Recording <a class="header-anchor" href="#capture-and-inspect-a-lab-recording" aria-label="Permalink to &quot;Capture And Inspect A Lab Recording&quot;">​</a></h1><p>Goal: run a Simulation Session, read its starting conditions, reliable motion segments and events, then check integrity and delete it independently.</p><p>Complete <a href="./simulation-session">fixed scenes and Simulation Sessions</a> first. Keep that chapter&#39;s <code>Shared Session</code> Lab, Installation, GLB asset and development data directory. Use the repository&#39;s Node and pnpm versions, plus Python with the pinned <code>websockets</code> dependency. Run the Bash commands from the repository root. This chapter uses the Synthetic development source. It requires no Newton, GPU or Docker.</p><h2 id="capture-one-run" tabindex="-1">Capture One Run <a class="header-anchor" href="#capture-one-run" aria-label="Permalink to &quot;Capture One Run&quot;">​</a></h2><p>If you stopped the previous chapter&#39;s server, restart it with the same directory:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LAB_WORD_SYNTHETIC_SESSION</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LAB_WORD_SYNTHETIC_PYTHON</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PWD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/.scratch/session-python/bin/python&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LAB_WORD_DATA_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.scratch/session-tutorial-data</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><ol><li>Open <a href="http://127.0.0.1:5173/lab" target="_blank" rel="noreferrer">http://127.0.0.1:5173/lab</a> and sign in as a Member.</li><li>Open the <code>Shared Session</code> Lab and <strong>Simulation Session</strong>.</li><li>Select the original Installation, then select <strong>Start</strong>.</li><li>Wait for <strong>Running</strong> and <strong>Motion connected</strong>.</li><li>Select <strong>Pause</strong> and wait for the paused state.</li><li>Wait several seconds, then select <strong>Resume</strong>.</li><li>Let it run for several seconds. Select <strong>Stop</strong> and wait for the stopped state.</li></ol><p>Start automatically creates one Recording. The server saves and syncs starting conditions before accepting the reliable source header and first frame. Running means initial reliable capture and live motion both passed admission. It does not prove a robot task succeeded.</p><p>The source retains each complete selected motion frame before offering it to the live sender. Live delivery can replace an older pending frame. Recording keeps every selected sample with no Viewer, a disconnected Viewer or a slow Viewer. Selected samples do not represent every physics solver step.</p><h2 id="read-the-recording-and-actual-segments" tabindex="-1">Read The Recording And Actual Segments <a class="header-anchor" href="#read-the-recording-and-actual-segments" aria-label="Permalink to &quot;Read The Recording And Actual Segments&quot;">​</a></h2><p>Run this in the Console of the authenticated Lab page:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> fetch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/api/v1/lab/labs&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">json</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()).data.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">map</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(({ </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  id,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  name,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}));</span></span></code></pre></div><p>Replace the Lab UUID below with the <code>Shared Session</code> identity. This bounded first-page query does not change the Lab:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> fetch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/api/v1/lab/labs/&lt;lab-uuid&gt;/recordings?limit=5&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">json</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).data.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">map</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(({ </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">session_id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">status</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">integrity</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">reason</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  id,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  session_id,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  status,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  integrity,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  reason,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}));</span></span></code></pre></div><p>Find the Recording UUID associated with the Session you just stopped. Paste this complete example into the Console:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// Paste into the Console of the authenticated, same-origin Lab page.</span></span>
<span class="line"><span>// These functions read bounded pages and one sealed segment. Delete is a separate explicit call.</span></span>
<span class="line"><span>const recordingUUID = (value) =&gt; {</span></span>
<span class="line"><span>  if (!/^[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}$/.test(value))</span></span>
<span class="line"><span>    throw new Error(&#39;Use a Lab or Recording UUID.&#39;);</span></span>
<span class="line"><span>  return value;</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span>const recordingHash = async (bytes) =&gt;</span></span>
<span class="line"><span>  &#39;sha256:&#39; +</span></span>
<span class="line"><span>  Array.from(</span></span>
<span class="line"><span>    new Uint8Array(await crypto.subtle.digest(&#39;SHA-256&#39;, bytes)),</span></span>
<span class="line"><span>    (byte) =&gt; byte.toString(16).padStart(2, &#39;0&#39;),</span></span>
<span class="line"><span>  ).join(&#39;&#39;);</span></span>
<span class="line"><span>async function recordingReadBytes(response, maximum) {</span></span>
<span class="line"><span>  if (!response.ok)</span></span>
<span class="line"><span>    throw new Error(\`Recording request failed: \${response.status}\`);</span></span>
<span class="line"><span>  if (!response.body) throw new Error(&#39;Recording response has no body.&#39;);</span></span>
<span class="line"><span>  const reader = response.body.getReader();</span></span>
<span class="line"><span>  const chunks = [];</span></span>
<span class="line"><span>  let size = 0;</span></span>
<span class="line"><span>  try {</span></span>
<span class="line"><span>    while (true) {</span></span>
<span class="line"><span>      const { value, done } = await reader.read();</span></span>
<span class="line"><span>      if (done) break;</span></span>
<span class="line"><span>      if (value.byteLength &gt; maximum - size)</span></span>
<span class="line"><span>        throw new Error(&#39;Recording response exceeds its read limit.&#39;);</span></span>
<span class="line"><span>      size += value.byteLength;</span></span>
<span class="line"><span>      chunks.push(value);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    const result = new Uint8Array(size);</span></span>
<span class="line"><span>    let offset = 0;</span></span>
<span class="line"><span>    for (const chunk of chunks) {</span></span>
<span class="line"><span>      result.set(chunk, offset);</span></span>
<span class="line"><span>      offset += chunk.byteLength;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    return result;</span></span>
<span class="line"><span>  } finally {</span></span>
<span class="line"><span>    await reader.cancel().catch(() =&gt; {});</span></span>
<span class="line"><span>    reader.releaseLock();</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>globalThis.inspectRecording = async function inspectRecording(</span></span>
<span class="line"><span>  labId,</span></span>
<span class="line"><span>  recordingId,</span></span>
<span class="line"><span>) {</span></span>
<span class="line"><span>  const path = \`/api/v1/lab/labs/\${recordingUUID(labId)}/recordings/\${recordingUUID(recordingId)}\`;</span></span>
<span class="line"><span>  const read = async (suffix, maximum = 256 * 1024) =&gt;</span></span>
<span class="line"><span>    JSON.parse(</span></span>
<span class="line"><span>      new TextDecoder(&#39;utf-8&#39;, { fatal: true }).decode(</span></span>
<span class="line"><span>        await recordingReadBytes(await fetch(path + suffix), maximum),</span></span>
<span class="line"><span>      ),</span></span>
<span class="line"><span>    );</span></span>
<span class="line"><span>  const metadata = await read(&#39;&#39;);</span></span>
<span class="line"><span>  const manifest = await read(&#39;/manifest&#39;, 2 * 1024 * 1024);</span></span>
<span class="line"><span>  const segments = await read(&#39;/segments?limit=5&#39;);</span></span>
<span class="line"><span>  const events = await read(&#39;/events?limit=5&#39;);</span></span>
<span class="line"><span>  const segment = segments.data.find((item) =&gt; item.sealed);</span></span>
<span class="line"><span>  const records = [];</span></span>
<span class="line"><span>  if (segment) {</span></span>
<span class="line"><span>    if (</span></span>
<span class="line"><span>      !Number.isInteger(segment.size) ||</span></span>
<span class="line"><span>      segment.size &lt; 36 ||</span></span>
<span class="line"><span>      segment.size &gt; 1024 * 1024</span></span>
<span class="line"><span>    )</span></span>
<span class="line"><span>      throw new Error(&#39;Select a sealed segment within the 1 MiB read limit.&#39;);</span></span>
<span class="line"><span>    const bytes = await recordingReadBytes(</span></span>
<span class="line"><span>      await fetch(path + \`/segments/\${segment.id}\`),</span></span>
<span class="line"><span>      segment.size,</span></span>
<span class="line"><span>    );</span></span>
<span class="line"><span>    if (</span></span>
<span class="line"><span>      bytes.byteLength !== segment.size ||</span></span>
<span class="line"><span>      (await recordingHash(bytes)) !== segment.sha256</span></span>
<span class="line"><span>    )</span></span>
<span class="line"><span>      throw new Error(&#39;Segment bytes do not match their size and SHA-256.&#39;);</span></span>
<span class="line"><span>    // LWF record: u32 little-endian JSON length, 32-byte SHA-256, exact UTF-8 JSON.</span></span>
<span class="line"><span>    let offset = 0;</span></span>
<span class="line"><span>    while (offset &lt; bytes.byteLength &amp;&amp; records.length &lt; 16) {</span></span>
<span class="line"><span>      if (bytes.byteLength - offset &lt; 36)</span></span>
<span class="line"><span>        throw new Error(&#39;Truncated segment record.&#39;);</span></span>
<span class="line"><span>      const size = new DataView(bytes.buffer).getUint32(offset, true);</span></span>
<span class="line"><span>      if (</span></span>
<span class="line"><span>        size &lt; 1 ||</span></span>
<span class="line"><span>        size &gt; 128 * 1024 ||</span></span>
<span class="line"><span>        size &gt; bytes.byteLength - offset - 36</span></span>
<span class="line"><span>      )</span></span>
<span class="line"><span>        throw new Error(&#39;Invalid segment record.&#39;);</span></span>
<span class="line"><span>      const payload = bytes.subarray(offset + 36, offset + 36 + size);</span></span>
<span class="line"><span>      const expected =</span></span>
<span class="line"><span>        &#39;sha256:&#39; +</span></span>
<span class="line"><span>        Array.from(bytes.subarray(offset + 4, offset + 36), (byte) =&gt;</span></span>
<span class="line"><span>          byte.toString(16).padStart(2, &#39;0&#39;),</span></span>
<span class="line"><span>        ).join(&#39;&#39;);</span></span>
<span class="line"><span>      if ((await recordingHash(payload)) !== expected)</span></span>
<span class="line"><span>        throw new Error(&#39;Record SHA-256 does not match.&#39;);</span></span>
<span class="line"><span>      records.push(</span></span>
<span class="line"><span>        JSON.parse(new TextDecoder(&#39;utf-8&#39;, { fatal: true }).decode(payload)),</span></span>
<span class="line"><span>      );</span></span>
<span class="line"><span>      offset += 36 + size;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>  const result = {</span></span>
<span class="line"><span>    recording_id: metadata.id,</span></span>
<span class="line"><span>    session_id: metadata.session_id,</span></span>
<span class="line"><span>    status: metadata.status,</span></span>
<span class="line"><span>    integrity: metadata.integrity,</span></span>
<span class="line"><span>    reason: metadata.reason,</span></span>
<span class="line"><span>    prefix: metadata.prefix,</span></span>
<span class="line"><span>    manifest: {</span></span>
<span class="line"><span>      snapshot_hash: manifest.snapshot_hash,</span></span>
<span class="line"><span>      captured_entities: manifest.capture_entity_ids.length,</span></span>
<span class="line"><span>      physics_entities: manifest.physics_entity_ids.length,</span></span>
<span class="line"><span>      versions: manifest.versions,</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>    segments: segments.data,</span></span>
<span class="line"><span>    next_segments_cursor: segments.next_cursor,</span></span>
<span class="line"><span>    events: events.data,</span></span>
<span class="line"><span>    next_events_cursor: events.next_cursor,</span></span>
<span class="line"><span>    verified_segment_id: segment?.id ?? null,</span></span>
<span class="line"><span>    first_record: records[0] ?? null,</span></span>
<span class="line"><span>    source_header:</span></span>
<span class="line"><span>      records.find((record) =&gt; record.kind === &#39;source.header&#39;)?.data</span></span>
<span class="line"><span>        .source_header ?? null,</span></span>
<span class="line"><span>    inspected_records: records.map(({ ordinal, kind }) =&gt; ({ ordinal, kind })),</span></span>
<span class="line"><span>  };</span></span>
<span class="line"><span>  console.log(result);</span></span>
<span class="line"><span>  return result;</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>globalThis.deleteRecording = async function deleteRecording(</span></span>
<span class="line"><span>  labId,</span></span>
<span class="line"><span>  recordingId,</span></span>
<span class="line"><span>) {</span></span>
<span class="line"><span>  const identity = await fetch(&#39;/api/v1/auth/session&#39;);</span></span>
<span class="line"><span>  if (!identity.ok) throw new Error(&#39;Sign in before deleting a Recording.&#39;);</span></span>
<span class="line"><span>  const { csrf_token: csrf } = await identity.json();</span></span>
<span class="line"><span>  const path = \`/api/v1/lab/labs/\${recordingUUID(labId)}/recordings/\${recordingUUID(recordingId)}\`;</span></span>
<span class="line"><span>  const response = await fetch(path, {</span></span>
<span class="line"><span>    method: &#39;DELETE&#39;,</span></span>
<span class="line"><span>    headers: { &#39;x-csrf-token&#39;: csrf },</span></span>
<span class="line"><span>  });</span></span>
<span class="line"><span>  if (!response.ok)</span></span>
<span class="line"><span>    throw new Error(\`Recording deletion refused: \${response.status}\`);</span></span>
<span class="line"><span>  console.log({ deleted_recording_id: recordingId, status: response.status });</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>Run <code>await inspectRecording(&#39;&lt;lab-uuid&gt;&#39;, &#39;&lt;recording-uuid&gt;&#39;)</code>.</p><p>The result includes Recording and Session identities, status, integrity, reason, reliable prefix, versions, and first pages of segments and events. After normal Stop completes, <code>status</code> and <code>integrity</code> are <code>complete</code>, and <code>prefix.source_ended</code> is <code>true</code>. Read again if the final segment is still being completed. Do not interpret temporary <code>open</code> status as complete.</p><p>The example reads at most five segments and five events, then downloads one sealed segment. It verifies segment size and SHA-256. It also checks up to the first 16 LWF records. <code>first_record</code> is usually the startup header. <code>source_header</code> shows an accepted source version header among those records. If it is null, inspect later records before interpreting dependency versions. When <code>verified_segment_id</code> is null, that page has no sealed segment yet. Read again after Stop.</p><p>A segment contains original facts. Each LWF record contains a little-endian u32 JSON length, a 32-byte SHA-256 and UTF-8 JSON. The <code>packet_base64</code> field in <code>source.packet</code> preserves original LWR1 bytes. Motion batches preserve original LWM1 frames. These bytes support independent checks without inferring Recording content from the Gateway&#39;s latest frame.</p><h2 id="understand-time-and-integrity" tabindex="-1">Understand Time And Integrity <a class="header-anchor" href="#understand-time-and-integrity" aria-label="Permalink to &quot;Understand Time And Integrity&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>snapshot_hash</code>, <code>manifest_sha256</code></td><td>Identities of the fixed snapshot and manifest. Current layout or asset updates do not rewrite them.</td></tr><tr><td><code>capture_baseline</code></td><td>Ordinary device state, active Commands and times when capture starts. Reset keeps the original physics snapshot and saves a new baseline.</td></tr><tr><td><code>versions</code>, <code>source.header</code></td><td>Server versions and source-reported code, Python and dependency versions. Unknown values stay null. Source reports are not independent installation proof.</td></tr><tr><td><code>recorded_at</code></td><td>Real time when the server records a fact. Ordinary device time continues during physics Pause.</td></tr><tr><td><code>sim_time_ns</code></td><td>Source simulation time as a decimal string. Ordinary Device Program events use null.</td></tr><tr><td><code>prefix</code></td><td>The contiguous synced source prefix. Motion sequence, source event sequence and global record ordinal have separate meanings.</td></tr><tr><td><code>incomplete</code>, <code>reason</code></td><td>Only preserved valid facts are assured. An unconfirmed tail can remain unknown; it does not prove there was no activity.</td></tr></tbody></table><p>Pause and Resume each save a new boundary frame and a <code>lifecycle.applied</code> event. Their simulation times can match, while sequences increase. Stop also saves the final source frontier and source-end fact. Complete status additionally requires saved server events and final segments.</p><p>Reset ends the old Session and Recording, then creates new identities for both. The new source starts at simulation time zero. The old Recording&#39;s time never moves backward. Ordinary Device Program Runs keep their own real-time behavior. Physics Pause, Reset and Stop do not stop their tasks.</p><p><code>capture_entity_ids</code> fixes the World membership at capture. <code>physics_entity_ids</code> includes only the Installation&#39;s physics-bound objects. Entities created later do not join this old Recording. Missing prior property values remain unknown.</p><p>A reliable ACK confirms only contiguous source facts whose file sync completed. Network send completion, live frame receipt and applied actions are separate confirmations. Capacity exhaustion, write failure, confirmation timeout or source failure stops or interrupts the Session and preserves explicit incomplete status. Actions do not replay automatically.</p><h2 id="pagination-and-sdk" tabindex="-1">Pagination And SDK <a class="header-anchor" href="#pagination-and-sdk" aria-label="Permalink to &quot;Pagination And SDK&quot;">​</a></h2><p>These reads require an active Member identity for the Lab, or an Agent key with <code>lab:full</code>:</p><table tabindex="0"><thead><tr><th>Method and path suffix</th><th>Result</th></tr></thead><tbody><tr><td><code>GET /recordings</code></td><td>Recording metadata page.</td></tr><tr><td><code>GET /recordings/{recording_id}</code></td><td>One Recording&#39;s metadata and integrity.</td></tr><tr><td><code>GET /recordings/{recording_id}/manifest</code></td><td>Fixed snapshot, current capture baseline, object membership and versions.</td></tr><tr><td><code>GET /recordings/{recording_id}/segments</code></td><td>Segment metadata page.</td></tr><tr><td><code>GET /recordings/{recording_id}/segments/{segment_id}</code></td><td>One segment&#39;s actual bytes.</td></tr><tr><td><code>GET /recordings/{recording_id}/events</code></td><td>Confirmed event page.</td></tr></tbody></table><p>All suffixes follow <code>/api/v1/lab/labs/{lab_id}</code>. List <code>limit</code> defaults to 20 and accepts 1 to 100. Event pages also have a 256 KiB budget. Keep <code>next_cursor</code> and send it as <code>cursor</code> to the same list. Segment and event cursors bind the current Recording. Start at the first page when changing Labs, Recordings or filters.</p><p>The generated SDK provides the same list and read methods. <a href="https://github.com/CaiZongyuan/labworld/blob/ed7dc6e0d4e1d8d939827668ad5d266f38673e67/packages/sdk/src/recording.ts" target="_blank" rel="noreferrer">readRecordingSegment</a> verifies one sealed segment, with a 1 MiB limit. The caller owns the AbortSignal and decides when to replace the current page. Do not combine an entire Recording&#39;s segments in memory.</p><h2 id="delete-independently" tabindex="-1">Delete Independently <a class="header-anchor" href="#delete-independently" aria-label="Permalink to &quot;Delete Independently&quot;">​</a></h2><ol><li>Start the same Installation again, run it for several seconds, then Stop to create Recording B.</li><li>Read A and B. Their Recording and Session identities differ, while they reference the same fixed GLB version.</li><li>Save one sealed segment identity and SHA-256 from B.</li><li>Explicitly run <code>await deleteRecording(&#39;&lt;lab-uuid&gt;&#39;, &#39;&lt;recording-a-uuid&gt;&#39;)</code>.</li><li>Query the Recording list again. A is removed.</li><li>Run <code>inspectRecording</code> for B. Its original segment and SHA-256 remain readable.</li></ol><p>Deletion changes persistent data. The function uses the current Member&#39;s CSRF token. An active Recording returns 409. Stop it before explicitly deleting it. Invalid identities return 401. Missing permissions or CSRF return 403. Cross-Lab or absent identities return 404. Obtain valid access, then repeat your explicit request.</p><p>Recording owns exact resource references. Deleting A releases only A&#39;s references. Files remain when B, a current asset or another consumer still uses them. Ordinary device history cleanup does not delete Recording facts.</p><h2 id="cause-an-isolated-write-failure" tabindex="-1">Cause An Isolated Write Failure <a class="header-anchor" href="#cause-an-isolated-write-failure" aria-label="Permalink to &quot;Cause An Isolated Write Failure&quot;">​</a></h2><p>Run this real process contract case from the repository root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test-concurrency=1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --experimental-strip-types</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test-name-pattern=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;recording write failure&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/e2e/recording-reliability.test.ts</span></span></code></pre></div><p>First run <code>pnpm install --frozen-lockfile</code> and use the repository&#39;s Node version. This case requires no Python, GPU or running tutorial server. It creates its own temporary data directory, loopback server and authenticated Machine source.</p><p>The case sends and retains externally confirmed t0 bytes. Test-process IPC then injects one failure before the next <code>source.packet</code> file write. The case sends another selected motion frame and reads the result through the official API.</p><p>Expect a passing Node test and a nonsecret <code>recording-write-failure</code> receipt. The next frame receives no durable ACK. The Session becomes interrupted. Recording becomes incomplete, with a write-failure reason. Its complete acknowledged t0 bytes remain readable through the segment API. The case cleans its processes, sockets and temporary data directory, then reconciles the ownership ledger.</p><p>The IPC fault applies only to this isolated test process. Tutorial data remains unchanged.</p><p>After a source crash or server process force-kill, reopening the same data directory preserves verifiable valid segments and interrupts the old Session. Unconfirmed tail facts can remain unknown. Durability evidence covers actual source/server process termination, sync and reopen checks. It does not cover operating-system crashes or power loss. Start a new Session explicitly.</p><h2 id="finish" tabindex="-1">Finish <a class="header-anchor" href="#finish" aria-label="Permalink to &quot;Finish&quot;">​</a></h2><p>Stop the active Session, close the Viewer, then stop development with Ctrl+C. The supervisor releases its Python source, both sockets and timers. Keep <code>.scratch/session-tutorial-data</code> and the Python environment, or remove them independently after confirming all consumers stopped.</p><p>Read <a href="./lab-records">Lab records</a> for ordinary history queries and retention. Recording queries describe saved facts from that experiment. Replay, external rendering, remote Newton and physics tasks remain future work.</p><hr><p>Source version：<code>ed7dc6e0d4e1</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/ed7dc6e0d4e1d8d939827668ad5d266f38673e67/docs/tutorials/recording.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,48)])])}const u=e(i,[["render",p]]);export{g as __pageData,u as default};
